/* CSS PART 1 OF 2 */

/* Design tokens */
:root {
  --ink: #202c30;
  --ink-soft: #46565a;
  --paper: #f6f5f0;
  --white: #ffffff;
  --brand: #244b48;
  --brand-dark: #183a38;
  --accent: #c58b53;
  --line: #dedfd8;
  --muted: #777f7c;
  --font-display: Georgia, "Times New Roman", serif;
  --font-body: "Helvetica Neue", Arial, sans-serif;
  --container: 1180px;
  --gutter: clamp(22px, 5vw, 76px);
  --radius: 3px;
  --shadow: 0 18px 50px rgba(20, 35, 33, .12);
}

/* Reset */
* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 4px;
}

::selection {
  color: var(--white);
  background: var(--brand);
}

/* Typography and shared layout */
h1,
h2,
h3,
p {
  margin-top: 0;
}

h1,
h2,
h3 {
  font-family: var(--font-display);
  font-weight: 400;
  line-height: 1.12;
  letter-spacing: -.035em;
}

h2 {
  font-size: clamp(2.3rem, 4vw, 3.8rem);
  margin-bottom: 22px;
}

h3 {
  font-size: 1.65rem;
}

p {
  color: var(--ink-soft);
}

.container {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
  color: var(--brand);
  font-size: .72rem;
  font-weight: 800;
  letter-spacing: .17em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 28px;
  height: 2px;
  background: var(--accent);
  content: "";
}

.section-intro {
  max-width: 690px;
  margin-bottom: 48px;
}

.section-intro p {
  max-width: 610px;
  font-size: 1.05rem;
}

.section-pad {
  padding-block: clamp(76px, 9vw, 126px);
}

/* Header and navigation */
.site-header {
  position: relative;
  z-index: 10;
  background: var(--white);
  border-bottom: 1px solid rgba(32, 44, 48, .08);
}

.header-inner {
  width: min(1360px, calc(100% - var(--gutter) * 1.2));
  min-height: 88px;
  margin-inline: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
}

.brand-lockup {
  display: inline-flex;
  align-items: center;
  gap: 13px;
  min-width: 0;
}

.brand-lockup img {
  width: 66px;
  height: 66px;
  object-fit: contain;
}

.brand-name {
  display: block;
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 1.08rem;
  line-height: 1.15;
}

.brand-caption {
  display: block;
  margin-top: 5px;
  color: var(--muted);
  font-size: .65rem;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.primary-nav {
  display: flex;
  align-items: center;
  gap: clamp(18px, 2.5vw, 36px);
}

.primary-nav a:not(.button) {
  color: var(--ink-soft);
  font-size: .84rem;
  font-weight: 700;
  transition: color .2s ease;
}

.primary-nav a:not(.button):hover {
  color: var(--accent);
}

/* Buttons */
.button {
  display: inline-flex;
  min-height: 52px;
  padding: 14px 23px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: var(--brand);
  color: var(--white);
  font-size: .78rem;
  font-weight: 800;
  letter-spacing: .08em;
  text-align: center;
  text-transform: uppercase;
  transition: background .2s ease, color .2s ease, border-color .2s ease;
}

.button:hover {
  background: var(--brand-dark);
}

.button-light {
  border-color: rgba(255, 255, 255, .75);
  background: transparent;
  color: var(--white);
}

.button-light:hover {
  border-color: var(--white);
  background: var(--white);
  color: var(--brand-dark);
}

.button-outline {
  border-color: var(--brand);
  background: transparent;
  color: var(--brand);
}

.button-outline:hover {
  background: var(--brand);
  color: var(--white);
}

/* Full-bleed hero */
.hero {
  position: relative;
  display: flex;
  min-height: min(760px, 82vh);
  min-height: min(760px, 82svh);
  align-items: center;
  overflow: hidden;
  isolation: isolate;
  background: var(--ink);
  color: var(--white);
}

.hero-media {
  position: absolute;
  z-index: -2;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 54%;
}

.hero::after {
  position: absolute;
  z-index: -1;
  inset: 0;
  background: linear-gradient(
    90deg,
    rgba(16, 29, 29, .88) 0%,
    rgba(16, 29, 29, .68) 48%,
    rgba(16, 29, 29, .12) 100%
  );
  content: "";
}

.hero-content {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin: 0 auto;
  padding-block: 110px;
}

.hero .eyebrow {
  color: #f0c18e;
}

.hero h1 {
  max-width: 780px;
  margin-bottom: 24px;
  color: var(--white);
  font-size: clamp(3.1rem, 6.8vw, 6.2rem);
  line-height: .99;
}

.hero-copy {
  max-width: 560px;
  margin-bottom: 34px;
  color: rgba(255, 255, 255, .88);
  font-size: clamp(1rem, 1.4vw, 1.18rem);
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 13px;
}

.hero-note {
  margin-top: 45px;
  color: rgba(255, 255, 255, .78);
  font-size: .76rem;
  font-weight: 700;
  letter-spacing: .13em;
  text-transform: uppercase;
}

/* Company introduction */
.intro-section {
  background: var(--white);
}

.intro-layout {
  display: grid;
  grid-template-columns: .9fr 1.1fr;
  align-items: center;
  gap: clamp(45px, 8vw, 110px);
}

.intro-copy {
  max-width: 590px;
}

.intro-copy p {
  font-size: 1.04rem;
}

.intro-image-wrap {
  position: relative;
  min-height: 450px;
}

.intro-image {
  width: 100%;
  height: 450px;
  object-fit: cover;
  object-position: center;
}

.experience-note {
  position: absolute;
  right: -18px;
  bottom: 25px;
  max-width: 225px;
  padding: 25px;
  background: var(--brand);
  color: var(--white);
  box-shadow: var(--shadow);
}

.experience-note strong {
  display: block;
  margin-bottom: 6px;
  color: var(--white);
  font-family: var(--font-display);
  font-size: 2rem;
  font-weight: 400;
}

.experience-note span {
  font-size: .76rem;
  line-height: 1.5;
}

/* Reasons to work with the company */
.why-section {
  background: var(--paper);
}

.why-layout {
  display: grid;
  grid-template-columns: .8fr 1.2fr;
  gap: clamp(45px, 8vw, 100px);
}

.why-heading {
  position: sticky;
  top: 35px;
  align-self: start;
}

.why-list {
  border-top: 1px solid var(--line);
}

.why-item {
  display: grid;
  grid-template-columns: 55px 1fr;
  gap: 22px;
  padding: 28px 0;
  border-bottom: 1px solid var(--line);
}

.why-number {
  color: var(--accent);
  font-family: var(--font-display);
  font-size: 1.65rem;
}

.why-item h3 {
  margin-bottom: 8px;
  font-size: 1.5rem;
}

.why-item p {
  max-width: 570px;
  margin-bottom: 0;
}

/* Roofing information */
.roof-section {
  background: var(--brand-dark);
  color: var(--white);
}

.roof-section h2,
.roof-section h3 {
  color: var(--white);
}

.roof-section .eyebrow {
  color: #edc08f;
}

.roof-section p {
  color: rgba(255, 255, 255, .78);
}

.roof-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: clamp(45px, 7vw, 90px);
}

.roof-image {
  width: 100%;
  height: 570px;
  object-fit: cover;
  object-position: center;
}

.roof-copy {
  max-width: 540px;
}

.roof-copy h2 {
  margin-bottom: 25px;
}

.roof-copy p {
  margin-bottom: 25px;
}

.roof-points {
  margin: 30px 0;
  padding: 0;
  list-style: none;
}

.roof-points li {
  position: relative;
  padding: 13px 0 13px 27px;
  border-bottom: 1px solid rgba(255, 255, 255, .17);
  color: rgba(255, 255, 255, .9);
}

.roof-points li::before {
  position: absolute;
  left: 0;
  color: #e5b47f;
  content: "—";
}

/* Colorado roofing guide */
.guide-section {
  background: var(--white);
}

.guide-layout {
  display: grid;
  grid-template-columns: .85fr 1.15fr;
  gap: clamp(45px, 8vw, 110px);
}

.guide-heading {
  align-self: start;
}

.guide-heading p {
  max-width: 440px;
}

.guide-steps {
  border-top: 1px solid var(--line);
}

.guide-step {
  display: grid;
  grid-template-columns: 65px 1fr;
  gap: 22px;
  padding: 25px 0;
  border-bottom: 1px solid var(--line);
}

.guide-step-number {
  color: var(--accent);
  font-family: var(--font-display);
  font-size: 2rem;
}

.guide-step h3 {
  margin-bottom: 8px;
}

.guide-step p {
  margin-bottom: 0;
}

/* Recent project gallery */
.projects-section {
  background: #eeeee8;
}

.projects-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 35px;
  margin-bottom: 45px;
}

.projects-heading .section-intro {
  margin-bottom: 0;
}

.project-gallery {
  display: grid;
  grid-template-columns: 1.05fr .95fr;
  grid-template-rows: 290px 290px;
  gap: 18px;
}

.project-item {
  position: relative;
  min-width: 0;
  overflow: hidden;
  background: var(--brand-dark);
}

.project-item:first-child {
  grid-row: span 2;
}

.project-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform .5s ease;
}

.project-item:hover img {
  transform: scale(1.035);
}

.project-caption {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  padding: 50px 25px 22px;
  background: linear-gradient(transparent, rgba(13, 24, 23, .85));
  color: var(--white);
}

.project-caption h3 {
  margin-bottom: 5px;
  color: var(--white);
  font-size: 1.5rem;
}

.project-caption p {
  margin-bottom: 0;
  color: rgba(255, 255, 255, .82);
  font-size: .8rem;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: .01ms !important;
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
  }
}
