/* CSS PART 2 OF 2 */

/* Contact and conversion */
.contact-section {
  padding-block: clamp(75px, 9vw, 120px);
  background: var(--white);
}

.contact-layout {
  display: grid;
  grid-template-columns: .85fr 1.15fr;
  gap: clamp(45px, 8vw, 105px);
  align-items: start;
}

.contact-copy {
  max-width: 460px;
}

.contact-copy h2 {
  margin-bottom: 24px;
}

.contact-details {
  margin-top: 35px;
  padding-top: 25px;
  border-top: 1px solid var(--line);
}

.contact-details p {
  margin-bottom: 8px;
}

.contact-form {
  padding: clamp(25px, 4vw, 48px);
  background: var(--paper);
  border: 1px solid var(--line);
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 21px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.form-field-full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--ink);
  font-size: .8rem;
  font-weight: 800;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  min-height: 50px;
  padding: 13px 15px;
  border: 1px solid #cfd2ca;
  border-radius: var(--radius);
  background: var(--white);
  color: var(--ink);
}

.form-field textarea {
  min-height: 145px;
  resize: vertical;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #818783;
}

.form-field input:focus-visible,
.form-field select:focus-visible,
.form-field textarea:focus-visible {
  border-color: var(--brand);
  outline: 3px solid rgba(36, 75, 72, .2);
  outline-offset: 2px;
}

.form-submit {
  margin-top: 25px;
}

.form-note {
  margin: 15px 0 0;
  color: var(--muted);
  font-size: .76rem;
}

/* Footer */
.site-footer {
  padding: 55px 0 25px;
  background: #172d2c;
  color: var(--white);
}

.footer-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
  padding-bottom: 40px;
}

.site-footer .brand-name {
  color: var(--white);
}

.site-footer .brand-caption {
  color: rgba(255, 255, 255, .65);
}

.footer-copy {
  max-width: 390px;
  margin: 0;
  color: rgba(255, 255, 255, .7);
  font-size: .88rem;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  gap: 25px;
  padding-top: 22px;
  border-top: 1px solid rgba(255, 255, 255, .17);
  color: rgba(255, 255, 255, .62);
  font-size: .75rem;
}

/* Accessible mobile navigation */
.menu-toggle {
  display: none;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--white);
  color: var(--brand);
  cursor: pointer;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 5px;
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

/* Large tablet and compact desktop */
@media (max-width: 1050px) {
  .header-inner {
    gap: 18px;
  }

  .primary-nav {
    gap: 17px;
  }

  .primary-nav a:not(.button) {
    font-size: .76rem;
  }

  .intro-layout,
  .why-layout,
  .roof-layout,
  .guide-layout,
  .contact-layout {
    gap: 40px;
  }

  .experience-note {
    right: 0;
  }
}

/* Tablet and mobile navigation */
@media (max-width: 760px) {
  :root {
    --gutter: 24px;
  }

  html {
    scroll-padding-top: 75px;
  }

  .header-inner {
    position: relative;
    min-height: 76px;
    flex-wrap: wrap;
    gap: 0;
  }

  .brand-lockup img {
    width: 53px;
    height: 53px;
  }

  .brand-name {
    font-size: .98rem;
  }

  .brand-caption {
    font-size: .58rem;
  }

  .menu-toggle {
    display: flex;
    flex: 0 0 44px;
  }

  .primary-nav {
    display: none;
    width: 100%;
    min-width: 0;
    max-height: calc(100svh - 90px);
    overflow-y: auto;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    padding: 10px 0 20px;
    border-top: 1px solid var(--line);
  }

  .primary-nav.is-open {
    display: flex;
  }

  .primary-nav a:not(.button) {
    display: block;
    width: 100%;
    padding: 13px 5px;
    font-size: .9rem;
  }

  .primary-nav .button {
    width: 100%;
    margin-top: 10px;
  }

  .hero {
    min-height: 690px;
    min-height: min(690px, 88svh);
    align-items: flex-end;
  }

  .hero-media {
    object-position: 58% center;
  }

  .hero::after {
    background: linear-gradient(
      0deg,
      rgba(16, 29, 29, .94) 0%,
      rgba(16, 29, 29, .72) 48%,
      rgba(16, 29, 29, .18) 100%
    );
  }

  .hero-content {
    padding-block: 90px 65px;
  }

  .hero h1 {
    max-width: 600px;
    font-size: clamp(3rem, 11vw, 5rem);
  }

  .hero-note {
    margin-top: 30px;
  }

  .section-pad {
    padding-block: 75px;
  }

  .intro-layout,
  .why-layout,
  .roof-layout,
  .guide-layout,
  .contact-layout {
    grid-template-columns: 1fr;
    gap: 35px;
  }

  .intro-image-wrap {
    min-height: 340px;
  }

  .intro-image {
    height: 340px;
  }

  .experience-note {
    right: 12px;
    bottom: 12px;
    max-width: 190px;
    padding: 19px;
  }

  .why-heading {
    position: static;
  }

  .roof-image {
    height: 400px;
  }

  .projects-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .project-gallery {
    grid-template-columns: 1fr 1fr;
    grid-template-rows: 340px 230px;
  }

  .project-item:first-child {
    grid-column: 1 / -1;
    grid-row: auto;
  }

  .contact-copy {
    max-width: 600px;
  }

  .footer-main {
    align-items: flex-start;
    flex-direction: column;
  }
}

/* Small mobile devices */
@media (max-width: 480px) {
  :root {
    --gutter: 20px;
  }

  body {
    font-size: 15px;
  }

  h2 {
    font-size: 2.45rem;
  }

  .brand-lockup {
    gap: 9px;
  }

  .brand-lockup img {
    width: 47px;
    height: 47px;
  }

  .brand-name {
    font-size: .87rem;
  }

  .brand-caption {
    font-size: .52rem;
    letter-spacing: .08em;
  }

  .hero {
    min-height: 650px;
    min-height: 85svh;
  }

  .hero-content {
    padding-block: 75px 48px;
  }

  .hero h1 {
    font-size: clamp(2.8rem, 12vw, 4rem);
  }

  .hero-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .hero-actions .button {
    width: 100%;
  }

  .hero-note {
    font-size: .66rem;
    letter-spacing: .09em;
  }

  .section-pad,
  .contact-section {
    padding-block: 65px;
  }

  .section-intro {
    margin-bottom: 32px;
  }

  .intro-image-wrap,
  .intro-image {
    height: 290px;
    min-height: 290px;
  }

  .experience-note {
    max-width: 165px;
    padding: 15px;
  }

  .experience-note strong {
    font-size: 1.7rem;
  }

  .why-item {
    grid-template-columns: 38px 1fr;
    gap: 13px;
    padding-block: 23px;
  }

  .roof-image {
    height: 310px;
  }

  .guide-step {
    grid-template-columns: 42px 1fr;
    gap: 13px;
  }

  .project-gallery {
    grid-template-columns: 1fr;
    grid-template-rows: 300px 260px 260px;
    gap: 14px;
  }

  .project-item:first-child {
    grid-column: auto;
  }

  .project-caption {
    padding: 45px 18px 17px;
  }

  .form-grid {
    grid-template-columns: 1fr;
    gap: 17px;
  }

  .form-field-full {
    grid-column: auto;
  }

  .contact-form {
    padding: 22px 17px;
  }

  .form-submit,
  .form-submit .button {
    width: 100%;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 8px;
  }
}

/* High contrast keyboard focus */
:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 4px;
}

button:focus-visible,
a:focus-visible {
  outline-color: #d79b61;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
}
